<?php
declare(strict_types=1);
if(getenv('LICORA_V2_TEST_ALLOW_SCHEMA_RESET')!=='1'){echo "Updater DB integration skipped (dedicated test DB not enabled).\n";exit(0);} $root=dirname(__DIR__);require_once $root.'/includes/updater/UpdateException.php';require_once $root.'/includes/updater/UpdateSchema.php';require_once $root.'/includes/updater/UpdateRepository.php';
function ud_ok($v,string $m):void{if(!$v){fwrite(STDERR,"FAIL: {$m}\n");exit(1);}}
$dsn=getenv('LICORA_TEST_DB_DSN')?:'';$user=getenv('LICORA_TEST_DB_USER')?:'';$pass=getenv('LICORA_TEST_DB_PASS')?:'';ud_ok($dsn!=='','test DSN required');$db=new PDO($dsn,$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);$schema=new UpdateSchema($db,$root.'/migration-v5.3.0-updater.sql');$status=$schema->ensure();ud_ok($status['ready'],'updater schema ready');ud_ok($schema->ensure()['ready'],'updater migration idempotent');$repo=new UpdateRepository($db);$job=$repo->createJob(['admin_id'=>null,'from_version'=>'5.3.0','target_version'=>'5.3.1','release_tag'=>'v5.3.1','release_url'=>'https://github.com/vibtools/Licora/releases/tag/v5.3.1','context'=>['fixture'=>true]]);ud_ok(strlen($job['job_uuid'])===36,'job persisted');$id=$repo->appendEvent($job['job_uuid'],'info','test','TEST_EVENT','Updater DB integration event');ud_ok($id>0,'event persisted');ud_ok(count($repo->eventsSince($job['job_uuid'],0))===1,'event stream readable');$repo->startMigration('test-updater-migration','5.3.1',str_repeat('a',64));$repo->finishMigration('test-updater-migration',5);$m=$repo->migration('test-updater-migration');ud_ok(($m['status']??'')==='applied','migration ledger persisted');$repo->updateJob($job['job_uuid'],['status'=>'success','stage'=>'complete','progress'=>100,'finished_at'=>date('Y-m-d H:i:s')]);echo "Updater DB integration checks passed.\n";
